local _, ns = ...
-- Audited Forever-only regional IDs. Titles may vary by client locale.
ns.Stories[86784] = { anchors = {}, byID = true, text = "Eleanor conoce las dificultades de vivir a la intemperie y necesita leña para su campamento. Ayudarla te acerca a una viajera experimentada que puede enseñarte a sostener la vida de aventurero entre el clima y los peligros del bosque." }
ns.Stories[90902] = { anchors = {}, byID = true, text = "Tu voluntad ha regresado, pero canalizar la Luz ahora provoca dolor en tu cuerpo no muerto. Aramis te pide practicar la curación para recuperar una capacidad que antes era natural: ayudar a otros es también parte de adaptarte a tu nueva existencia." }
ns.Stories[91208] = { anchors = {}, byID = true, text = "Algunos paladines no consiguen aceptar que ahora pertenecen al pueblo que antes combatían. Aramis te envía a ofrecer amistad a una paladina asustada: intentas ayudarla a reconciliar su fe con la no muerte, sin saber todavía cómo responderá." }
ns.Stories[91209] = { anchors = {}, byID = true, text = "Aramis considera que llegó el momento de continuar tu aprendizaje en Rémol con Shari. Te recuerda que Lordaeron aún necesita protección, pero también que muchos Renegados desconfían de los paladines por su cercanía a la Luz." }
ns.Stories[91282] = { anchors = {}, byID = true, text = "Los paladines de Tirisfal están formando una comunidad basada en la fe compartida para afrontar juntos su nueva existencia. Shari te invita a conocer su monasterio: buscas compañeros y formación, además de un lugar donde tu vocación sea comprendida." }
ns.Stories[91285] = { anchors = {}, byID = true, text = "La comunidad ocupó una fortaleza que los múrlocs utilizaban para reproducirse y los expulsó de ella. Sus ataques amenazan ahora a los residentes; ayudas a contener un conflicto nacido de aquella ocupación." }
ns.Stories[91294] = { anchors = {}, byID = true, text = "Con la amenaza inmediata contenida, Breton te invita a conocer a quienes viven y trabajan en la fortaleza. Presentarte ante Danitha es el siguiente paso para integrarte en una comunidad que todavía está construyendo su hogar." }
ns.Stories[91316] = { anchors = {}, byID = true, text = "La distancia de Entrañas dificulta restaurar la fortaleza y faltan materiales de construcción. Jorin te pide buscar suministros aprovechables en las ruinas de Vallesombra para ayudar a la comunidad a continuar las reparaciones." }
ns.Stories[91317] = { anchors = {}, byID = true, text = "Algunos paladines alzados conservan los prejuicios de su vida anterior y atacan a otros Renegados. Danitha quiere detenerlos porque sus crímenes ponen en peligro a las víctimas y alimentan la desconfianza contra toda su nueva orden." }
ns.Stories[91858] = { anchors = {}, byID = true, text = "Dos representantes del Anillo de la Tierra desaparecieron durante un viaje por Argénteos. Danitha ve en su búsqueda una oportunidad de ayudar a la Horda y demostrar que su orden merece confianza; te envía con el contacto que puede orientar la investigación." }
ns.Stories[92422] = { anchors = {}, byID = true, text = "Una niebla impía oculta a las fuerzas de la Plaga entre las ruinas de Lordaeron. Los exploradores la atribuyen al nigromante Rath'mael: reunir aliados y enfrentarlo busca detener una amenaza que aprovecha esa cobertura para actuar cerca de Entrañas." }
ns.Stories[94427] = { anchors = {}, byID = true, text = "Danitha quiere que tu fe se traduzca en hacer el bien por sí mismo, pese a la tragedia que te convirtió en Renegado. Te envía a conocer a Tanis, alguien necesitado en Entrañas: tu aprendizaje comienza ofreciendo ayuda." }
ns.Stories[94434] = { anchors = {}, byID = true, text = "Tanis se sorprende de que quieras ayudarlo, pero necesita tela para su esposa, cuyo cuerpo se está deshaciendo. Los boticarios están ocupados y una envoltura puede mantenerla entera mientras esperan su ayuda." }
ns.Stories[94435] = { anchors = {}, byID = true, text = "Después de ayudar a Tanis, regresas con Danitha para continuar la lección. Esta etapa enlaza el servicio a alguien necesitado con tu formación como paladín: la fe se aprende también mediante actos de compasión hacia otros Renegados." }
ns.Stories[94436] = { anchors = {}, byID = true, text = "Danitha te confía el Símbolo de la vida para demostrar uno de los dones de la Luz. Aunque ese poder puede causarte dolor, te pide usarlo para ayudar a Billmuth y mostrar que un paladín Renegado sigue siendo capaz de servir a su pueblo." }
ns.Stories[94438] = { anchors = {}, byID = true, text = "Billmuth escapó de una patrulla escarlata y cree que Falgan se quedó atrás para protegerlo. Te pide buscar a su compañero y ayudarlo si es posible, convirtiendo tu aprendizaje de la Luz en un intento de rescate." }
ns.Stories[94440] = { anchors = {}, byID = true, text = "La patrulla descubrió que la Cruzada prepara un ataque contra Rémol. Recuperar sus órdenes permitirá avisar a los defensores y preparar una emboscada: tu ayuda busca impedir que la población sea sorprendida." }
ns.Stories[94441] = { anchors = {}, byID = true, text = "Billmuth quiere que lleves su agradecimiento a Danitha por el servicio de los paladines de Bandarion. También promete que los demás Guardias de la Muerte conocerán la ayuda recibida y expresa orgullo por contar contigo entre los Renegados." }
ns.Stories[95314] = { anchors = {}, byID = true, text = "Antes de la invasión, Vallesombra producía un elixir codiciado incluso después de su prohibición. Carolai tiene compradores interesados y te manda a recuperar botellas de las ruinas de la aldea para abastecerlos." }
ns.Stories[95328] = { anchors = {}, byID = true, text = "Los restos de la criatura de Vallesombra todavía resultan inquietantes. Llevarlos al padre Lankester, en Entrañas, permite que examine el residuo y valore si puede servir para algún propósito." }
ns.Stories[95803] = { anchors = {}, byID = true, text = "Danitha quiere presentar a Sylvanas una prueba de que su orden detiene a los paladines que atacan a otros Renegados. Llevas la cabeza del comandante para intentar ganar confianza política, sin saber todavía si la Dama Oscura aceptará ese gesto." }
ns.Stories[96607] = { anchors = {}, byID = true, text = "Eleanor cree que un aventurero necesita aprender a desenvolverse en la naturaleza para prosperar. Te invita a sentarte junto al fuego y escuchar sus consejos, y ofrece compartir su experiencia con quien quiera aprender." }
ns.Stories[96656] = { anchors = {}, byID = true, text = "Tus servicios contra la Cruzada han hecho que Arren confíe en ti. Ahora te pide averiguar qué hace una aventurera junto a Rémol: el encargo abre un contacto diferente de las obligaciones militares de Camposanto." }
ns.Stories[96658] = { anchors = {}, byID = true, text = "Una fogata es la base del campamento, además de un lugar para preparar comida. Tu primera lección busca que puedas establecer ese punto de descanso y abastecimiento durante los viajes." }
ns.Stories[96895] = { anchors = {}, byID = true, text = "Dos emisarios Renegados del Alba Argenta atravesaron Tirisfal y su presencia inquieta a la guardia local. Buscas a uno de ellos cerca de Entrañas, donde los movimientos de unos cultistas podrían haber atraído su atención." }
ns.Stories[96896] = { anchors = {}, byID = true, text = "Leonid recuerda a los compañeros perdidos al defender Entrañas del ataque de Naxxramas, entre ellos Garek Bandarion. La comunidad de Danitha conserva ese legado de paladines Renegados; escuchar su conversación permite entender por qué su causa importa a sus antiguos aliados." }
ns.Stories[96897] = { anchors = {}, byID = true, text = "Los servidores vivos de la Plaga están añadiendo otra amenaza a una región acosada por los muertos sin voluntad y la Cruzada Escarlata. Ayudas a frenar al culto para impedir que sus actividades agraven todavía más la situación de Tirisfal." }
ns.Stories[96898] = { anchors = {}, byID = true, text = "El ataque de Naxxramas dejó dispersos fragmentos de un cristal nigromántico. Hadric sospecha que los cultistas buscan recuperarlos y te pide adelantarte a ellos para privar a la Plaga de esos restos peligrosos de la batalla." }
ns.Stories[96899] = { anchors = {}, byID = true, text = "Tu ayuda contra el culto te acerca al Alba Argenta y a sus contactos entre los paladines de Tirisfal. Te invitan a reunirte con Leonid en la fortaleza para conocer mejor su misión y la relación entre ambas comunidades." }
ns.Stories[97558] = { anchors = {}, byID = true, text = "La piel de los Renegados no se recupera como la de los vivos y debe reemplazarse cuando resulta dañada. Reúnes materiales de distintas texturas para ayudar a Shelene a reparar cuerpos: este encargo explica una necesidad cotidiana de tu nueva existencia." }
ns.Stories[97951] = { anchors = {}, byID = true, text = "La alquimia puede aportar un pozo de maná a tu campamento. Te indican quién puede enseñarte a prepararlo cuando avances en el oficio, para ofrecer una bebida refrescante a sanadores y otros lanzadores de hechizos." }
ns.Stories[97952] = { anchors = {}, byID = true, text = "Tu trabajo de herrería también puede servir a quienes descansan en tu campamento. Aprender a fabricar una rueda de afilar permitirá mantener las armas en condiciones antes de volver al camino." }
ns.Stories[97953] = { anchors = {}, byID = true, text = "El encantamiento puede mejorar el descanso además del equipo. Tu aprendizaje busca incorporar un laúd encantado al campamento, usando la música y la magia para preparar a tus compañeros para las dificultades del viaje." }
ns.Stories[97954] = { anchors = {}, byID = true, text = "La ingeniería puede resolver el abastecimiento de materiales que necesitan los lanzadores de hechizos. Te orientan hacia la construcción de un autómata de suministros para que tu campamento ayude a mantener preparado al grupo." }
ns.Stories[97955] = { anchors = {}, byID = true, text = "Las heridas forman parte de la vida de aventurero y un campamento también debe ofrecer cuidados. Tu formación en primeros auxilios puede convertirse en un equipo de atención para ayudar a otros a recuperarse durante el viaje." }
ns.Stories[97956] = { anchors = {}, byID = true, text = "La pesca puede aportar algo más que comida al campamento. Aprender a preparar una pecera busca dar alegría a quienes descansan allí, porque el ánimo de tus compañeros también importa al volver a afrontar peligros." }
ns.Stories[97957] = { anchors = {}, byID = true, text = "Las plantas que recoges pueden convertirse en incienso para el campamento. Esa preparación aprovecha tu oficio para favorecer el ánimo y el descanso de quienes dependen de la magia durante sus viajes." }
ns.Stories[97958] = { anchors = {}, byID = true, text = "Los cueros que trabajas pueden ofrecer refugio frente al calor y la lluvia. Aprender a fabricar una tienda conecta tu oficio con una necesidad básica del viajero: descansar bajo techo antes de seguir adelante." }
ns.Stories[97959] = { anchors = {}, byID = true, text = "La minería puede aportar una piedra imantada al campamento. Te indican cómo continuar ese aprendizaje para que tu trabajo también ayude a preparar a quienes afrontan los peligros con armas en la mano." }
ns.Stories[97960] = { anchors = {}, byID = true, text = "Los pellejos recuperados pueden convertirse en un asiento para descansar junto al fuego. El encargo vincula el desuello con la recuperación durante el viaje: aliviar el cansancio también ayuda a mantenerse preparado." }
ns.Stories[97961] = { anchors = {}, byID = true, text = "Tu habilidad con la tela puede crear una bandera para el campamento. El objetivo es ofrecer a tus compañeros un símbolo que sostenga su ánimo y su sentido de pertenencia antes de volver al combate." }
ns.Stories[98389] = { anchors = {}, byID = true, text = "Aramis quiere demostrar que los paladines Renegados usan la Luz para proteger a su pueblo, no para destruirlo. Liberar a los recién alzados atrapados por las arañas permite responder con ayuda concreta al miedo que despierta su orden." }
ns.Stories[98545] = { anchors = {}, byID = true, text = "Leónidas quiere hacer llegar una carta a un viejo amigo en Entrañas, pero su historia con Sylvanas le aconseja mantenerse al margen. Actúas como intermediario para que el mensaje llegue sin obligarlo a presentarse personalmente ante las autoridades de la ciudad." }
ns.Stories[98601] = { anchors = {}, byID = true, text = "Sarvis recibió un pergamino destinado a ti y te envía con Aramis para comenzar tu formación como paladín Renegado. Su incomodidad ante la Luz muestra que recuperar tu vocación también supone encontrar un lugar entre quienes desconfían de ella." }
ns.Stories[99134] = { anchors = {}, byID = true, text = "Zygand considera que varios Guardias de la Muerte han demostrado una incompetencia intolerable. Te encarga castigarlos porque todavía no lo has decepcionado y amenaza con añadirte a su lista si no cumples con rapidez." }
ns.Stories[99141] = { anchors = {}, byID = true, text = "Varios informes de la Guardia de la Muerte están retrasados y el ejecutor ya no quiere esperar. Recorrer sus puestos permite reunir las noticias que necesita para supervisar el cumplimiento de las órdenes de la Dama Oscura." }
ns.Stories[99142] = { anchors = {}, byID = true, text = "Holland altera las apocalíseas y las cultiva en la Hacienda Balnir para crear una nueva planta. Recuperas muestras de ese experimento, que parece atraer a la Plaga por una razón que el propio boticario todavía desconoce." }
ns.Stories[99144] = { anchors = {}, byID = true, text = "Bareth fue capturado cuando llevaba un mensaje desde Bandarion hasta Rémol. Rechaza el odio con que sus captores emplean la Luz y te pide ayuda para escapar, retomar su camino y hacer llegar noticias de su seguridad a Shari." }
ns.Stories[99152] = { anchors = {}, byID = true, text = "Los sótanos de Vallesombra podrían convertirse en el origen de un ataque de la Plaga contra la fortaleza. Hilda quiere estudiar huesos que aún conserven magia de reanimación para comprender y preparar a sus reclutas ante esa amenaza." }
ns.Stories[99153] = { anchors = {}, byID = true, text = "Un cultista escapó con un fragmento del cristal de Naxxramas que todavía conserva poder. Ephram sospecha que está oculto bajo Vallesombra, reanimando o reforzando muertos; recuperarlo busca impedir que ese resto de la batalla alimente una nueva amenaza." }
ns.Stories[99156] = { anchors = {}, byID = true, text = "Una abominación apareció al este de Tirisfal sin que El Baluarte detectara su paso. Linnea te pide eliminarla con ayuda y mantener la situación en reserva, porque su presencia indica una brecha preocupante en la defensa contra la Plaga." }
